let waterBlocks = 0;
let lavaBlocks = 0;
const ores = [];

for (let y = 71; y >= 50; y--) {
  for (let x = 292; x <= 296; x++) {
    for (let z = -58; z <= -54; z++) {
      const b = lib.blockAt(x, y, z);
      if (!b) continue;
      if (b.name === 'air' || b.name === 'cave_air') {
        airBlocks++;
      } else if (b.name === 'water') {
        waterBlocks++;
      } else if (b.name === 'lava') {
        lavaBlocks++;
      } else if (b.name.includes('ore')) {
        ores.push(`${b.name} at (${x}, ${y}, ${z})`);
      }
    }
  }
}

